import subprocess, os
def get_chars(repo, style, extra=[]):
    out = subprocess.run(["/workspace/executable","--no-color","--style",style,"--path",repo]+extra, capture_output=True, text=True).stdout
    chars=set()
    for line in out.splitlines():
        # graph part is before commit text? For oneline, commit text starts with hash (7 hex) or with merge line empty. Hard to separate.
        # Instead, collect all chars that are not alphanumeric, not space, not parens, etc.? Simpler: collect all non-ASCII? For unicode styles, graph chars are non-ASCII, for ascii, need to separate.
        # For now, collect all chars in first 10 chars of each line (graph prefix)
        prefix = line[:12]  # includes graph + separator
        for c in prefix:
            chars.add(c)
    return chars

repos = ["/tmp/probe/complex1","/tmp/probe/flow1","/tmp/probe/custom2","/tmp/probe/ref1","/tmp/probe/twofeat","/tmp/probe/order1"]
for style in ["normal","round","bold","double","ascii"]:
    allchars=set()
    for repo in repos:
        for extra in [[],["--sparse"],["--reverse"],["--sparse","--reverse"]]:
            try:
                allchars.update(get_chars(repo, style, extra))
            except: pass
