    # Use datetime from timestamp (UTC)
    try:
        dt = datetime.datetime.utcfromtimestamp(timestamp)
        # Weekday abbrev, month abbrev, day space-padded, time, year, +0000?
        # Python strftime %e is space-padded day (Unix), but not on all platforms? Use manual.
        weekdays = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun']
        months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']
