def build_display_data(commits, assigned, refs_info, model_data):
    # commits: list newest first (truncated, sorted)
    # assigned: hash->branch
    # Returns: display_commits (filtered to assigned, in order), branch_to_col, col_to_branch, branch_ranges, etc.
    # Filter to assigned
    display = [c for c in commits if c['H'] in assigned]
    # If reverse? Handle later (for now assume normal order newest first)
    # Build branch list with assigned commits
    branches = set(assigned[h] for h in [c['H'] for c in display])
    # Compute order groups for columns
    branch_order_idx = {}
    order_list = model_data.get('order', [])
    for b in branches:
        og = len(order_list)
        for idx, pat in enumerate(order_list):
            try:
                # Handle fork/ prefix? For real branches, no fork. For synthetic unknown/fork/unknown/tags, need to handle?
                # For tags branches like 'tags/v1.0', match against order patterns (which include '^tags/.*$' for simple? For git-flow, order doesn't include tags, so tags unmatched (rightmost). Good.
                if re.search(pat, b):
                    og = idx
                    break
            except:
                pass
        branch_order_idx[b] = og
    # Sort branches by order_group, then by persistence? Or by name? For structured, use order_group, then persistence, then name.
    persist_list = model_data.get('persistence', [])
    branch_persist_idx = {}
    for b in branches:
        pi = len(persist_list)
        # For persistence, strip fork/ prefix? Docs: fork/ only in order/colors, not persistence. So for branches like 'fork/unknown', strip prefix for persistence matching? But our branches are real names (no fork), so same.
        # For synthetic 'fork/unknown', strip to 'unknown' for persistence? Good to handle.
        check_name = b
        if b.startswith('fork/'):
            check_name = b[5:]
        for idx, pat in enumerate(persist_list):
            try:
                if re.search(pat, check_name):
                    pi = idx
                    break
            except:
                pass
        branch_persist_idx[b] = pi
    # Sort for columns: by order_group, then persistence, then name
    sorted_branches = sorted(branches, key=lambda b: (branch_order_idx[b], branch_persist_idx[b], b))
    # Assign cols
    branch_to_col = {b:i for i,b in enumerate(sorted_branches)}
    col_to_branch = {i:b for b,i in branch_to_col.items()}
    num_cols = len(sorted_branches)
    # Compute ranges: for each branch, min/max display index where assigned
    hash_to_idx = {c['H']: i for i,c in enumerate(display)}
    branch_ranges = {}
    for b in branches:
        idxs = [hash_to_idx[c['H']] for c in display if assigned[c['H']]==b]
        if idxs:
            branch_ranges[b] = (min(idxs), max(idxs))
        else:
            branch_ranges[b] = (None, None)
    return display, branch_to_col, col_to_branch, num_cols, branch_ranges, hash_to_idx

